    }
    cout << "Highest average row: " << bestRow + 1 << " (" << bestAvg << ")" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int r, c;
    cin >> r >> c;
    int a[50][50];
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            cin >> a[i][j];
        }
    }
    int rowGroups = 0;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            if (a[i][j] == 1 && (j == 0 || a[i][j - 1] == 0)) {
                rowGroups++;
            }
        }
    }
    int colGroups = 0;
    for (int j = 0; j < c; j++) {
        for (int i = 0; i < r; i++) {
            if (a[i][j] == 1 && (i == 0 || a[i - 1][j] == 0)) {
                colGroups++;
            }
        }
    }
    cout << "Row groups: " << rowGroups << endl;
    cout << "Column groups: " << colGroups << endl;
    return 0;
}

